versions.variantCss:
.wemd-hero-banner[data-variant="bytedance-hero-neon"] {
  background: linear-gradient(135deg, var(--wemd-primary), var(--wemd-primary-dark));
  border-radius: var(--wemd-border-radius);
  padding: 56px 32px 48px 32px;
  margin: 0 0 24px 0;
  text-align: center;
  box-shadow: var(--wemd-shadow);
  overflow: hidden;
}
.wemd-hero-banner[data-variant="bytedance-hero-neon"] .wemd-component-body {
  position: relative;
  z-index: 2;
}
.wemd-hero-banner[data-variant="bytedance-hero-neon"] .wemd-component-body .wemd-child-1 {
  color: #ffffff;
  font-size: 32px;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.5px;
  margin: 0 0 12px 0;
}
.wemd-hero-banner[data-variant="bytedance-hero-neon"] .wemd-component-body .wemd-child-2 {
  color: rgba(255, 255, 255, 0.9);
  font-size: 16px;
  font-weight: 400;
  line-height: 1.6;
  margin: 0 0 24px 0;
}
.wemd-hero-banner[data-variant="bytedance-hero-neon"] .wemd-component-body .wemd-child-3 {
  display: inline-block;
  background: #ffffff;
  color: var(--wemd-primary);
  font-size: 15px;
  font-weight: 700;
  padding: 10px 28px;
  border-radius: 999px;
  margin: 0;
}
